class Solution {

    public int canCompleteCircuit(int[] gas, int[] cost) {
        int total = 0,
            tank = 0,
            start = 0;
        for (int i = 0; i < gas.length; i++) {
            int d = gas[i] - cost[i];
            total += d;
            tank += d;
            if (tank < 0) {
                // nothing in [start..i] can work
                start = i + 1;
                tank = 0;
            }
        }
        return total >= 0 ? start : -1;
    }
}

