    public List<Integer> partitionLabels(String s) {
        List<Integer> res = new ArrayList<>();
        int start = 0,
            end = 0;
        for (int i = 0; i < s.length(); i++) {
            end = Math.max(end, s.lastIndexOf(s.charAt(i))); // O(n) scan each time
            if (i == end) {
                res.add(end - start + 1);
                start = i + 1;
            }
        }
        return res;
    }
}

