class Solution {

    public boolean checkValidString(String s) {
        int n = s.length();
        Boolean[][] memo = new Boolean[n + 1][n + 1];
        return go(s, 0, 0, memo);
    }

    private boolean go(String s, int i, int open, Boolean[][] memo) {
        if (open < 0 || open > s.length()) return false;
        if (i == s.length()) return open == 0;
        if (memo[i][open] != null) return memo[i][open];
        char c = s.charAt(i);
        boolean res;
        if (c == '(') res = go(s, i + 1, open + 1, memo);
        else if (c == ')') res = go(s, i + 1, open - 1, memo);
        else res =
            go(s, i + 1, open + 1, memo) ||
            go(s, i + 1, open - 1, memo) ||
            go(s, i + 1, open, memo);
        return (memo[i][open] = res);
    }
}

