class Solution {

    public boolean checkValidString(String s) {
        int lo = 0,
            hi = 0; // min and max possible open count
        for (char c : s.toCharArray()) {
            if (c == '(') {
                lo++;
                hi++;
            } else if (c == ')') {
                lo--;
                hi--;
            } else {
                lo--;
                hi++;
            } // '*' could be ')' or '('
            if (hi < 0) return false; // too many ')' no matter what
            if (lo < 0) lo = 0; // never allow negative open count
        }
        return lo == 0;
    }
}

