class Solution {

    public int[][] insert(int[][] intervals, int[] newInterval) {
        List<int[]> res = new ArrayList<>();
        int i = 0,
            n = intervals.length;
        int s = newInterval[0],
            e = newInterval[1];
        while (i < n && intervals[i][1] < s) res.add(intervals[i++]); // fully left
        while (i < n && intervals[i][0] <= e) {
            // overlapping
            s = Math.min(s, intervals[i][0]);
            e = Math.max(e, intervals[i][1]);
            i++;
        }
        res.add(new int[] { s, e });
        while (i < n) res.add(intervals[i++]); // fully right
        return res.toArray(new int[0][]);
    }
}

