class Solution {

    public int minMeetingRooms(int[][] intervals) {
        int n = intervals.length;
        int[] starts = new int[n],
            ends = new int[n];
        for (int k = 0; k < n; k++) {
            starts[k] = intervals[k][0];
            ends[k] = intervals[k][1];
        }
        Arrays.sort(starts);
        Arrays.sort(ends);
        int rooms = 0,
            best = 0,
            j = 0;
        for (int i = 0; i < n; i++) {
            while (ends[j] <= starts[i]) {
                // free rooms whose meeting already ended
                rooms--;
                j++;
            }
            rooms++; // this meeting takes a room
            best = Math.max(best, rooms);
        }
        return best;
    }
}

