class MinHeap {
    constructor(less) {
        this.a = [];
        this.less = less;
    }
    size() {
        return this.a.length;
    }
    peek() {
        return this.a[0];
    }
    push(x) {
        const a = this.a;
        a.push(x);
        let i = a.length - 1;
        while (i > 0) {
            // sift up
            const p = (i - 1) >> 1;
            if (!this.less(a[i], a[p])) break;
            [a[i], a[p]] = [a[p], a[i]];
            i = p;
        }
    }
    pop() {
        const a = this.a,
            top = a[0],
            last = a.pop();
        if (a.length) {
            a[0] = last;
            let i = 0;
            while (true) {
                // sift down
                const l = 2 * i + 1,
                    r = l + 1;
                let m = i;
                if (l < a.length && this.less(a[l], a[m])) m = l;
                if (r < a.length && this.less(a[r], a[m])) m = r;
                if (m === i) break;
                [a[i], a[m]] = [a[m], a[i]];
                i = m;
            }
        }
        return top;
    }
}

var minInterval = function (intervals, queries) {
    intervals.sort((a, b) => a[0] - b[0]);
    const order = queries
        .map((_, k) => k)
        .sort((a, b) => queries[a] - queries[b]);
    const heap = new MinHeap((x, y) => x[0] < y[0]); // [size, right]
    const ans = new Array(queries.length);
    let i = 0;
    for (const idx of order) {
        const q = queries[idx];
        while (i < intervals.length && intervals[i][0] <= q) {
            // started
            const [l, r] = intervals[i++];
            heap.push([r - l + 1, r]);
        }
        while (heap.size() && heap.peek()[1] < q) heap.pop(); // expired
        ans[idx] = heap.size() ? heap.peek()[0] : -1;
    }
    return ans;
};

