                    changed = true;
                }
                if (
                    i < n - 1 &&
                    ratings[i] > ratings[i + 1] &&
                    c[i] <= c[i + 1]
                ) {
                    c[i] = c[i + 1] + 1;
                    changed = true;
                }
            }
        }
        int sum = 0;
        for (int x : c) sum += x;
        return sum;
    }
}

