class Solution {

    public int candy(int[] ratings) {
        int n = ratings.length;
        int total = 1,
            up = 0,
            down = 0,
            peak = 0;
        for (int i = 1; i < n; i++) {
            if (ratings[i] > ratings[i - 1]) {
                // going up
                up++;
                peak = up;
                down = 0;
                total += 1 + up;
            } else if (ratings[i] == ratings[i - 1]) {
                // flat: restart
                up = down = peak = 0;
                total += 1;
            } else {
                // going down
                up = 0;
                down++;
                total += 1 + down - (peak >= down ? 1 : 0); // peak grows only if down > peak
            }
        }
        return total;
    }
}

