class Solution {

    public ArrayList<Integer> jobSequencing(
        int[] deadline,
        int[] profit
    ) {
        int n = deadline.length,
            maxD = 0;
        for (int d : deadline) maxD = Math.max(maxD, d);
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) ->
            Integer.compare(profit[b], profit[a])
        ); // richest first
        boolean[] used = new boolean[maxD + 1];
        int count = 0,
            total = 0;
        for (int i : idx) {
            for (int t = deadline[i]; t >= 1; t--) {
                // latest free slot <= deadline
                if (!used[t]) {
                    used[t] = true;
                    count++;
                    total += profit[i];
                    break;
                }
            }
        }
        return new ArrayList<>(Arrays.asList(count, total));
    }
}

