class Solution {

    public ArrayList<Integer> jobSequencing(
        int[] deadline,
        int[] profit
    ) {
        int n = deadline.length,
            maxD = 0;
        for (int d : deadline) maxD = Math.max(maxD, d);
        int D = Math.min(maxD, n);
        int[] parent = new int[D + 1];
        for (int t = 0; t <= D; t++) parent[t] = t;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) ->
            Integer.compare(profit[b], profit[a])
        ); // richest first
        int count = 0;
        long total = 0; // long in case profits sum large
        for (int i : idx) {
            int s = find(parent, Math.min(deadline[i], D)); // latest free slot <= deadline
            if (s > 0) {
                count++;
                total += profit[i];
                parent[s] = s - 1; // slot s is used: point left
            }
        }

        return new ArrayList<>(Arrays.asList(count, (int) total));
    }

    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path halving
            x = parent[x];
        }
        return x;
    }
}

