        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path halving
            x = parent[x];
        }
        return x;
    };
    const idx = [...Array(n).keys()].sort(
        (a, b) => profit[b] - profit[a],
    ); // richest first
    let count = 0,
        total = 0;
    for (const i of idx) {
        const s = find(Math.min(deadline[i], D)); // latest free slot <= deadline
        if (s > 0) {
            count++;
            total += profit[i];
            parent[s] = s - 1; // slot s is used: point left
        }
    }
    return [count, total];
}
